 $('#pause-game').onclick=togglePause;$('#exit-game').onclick=()=>{if(zenMode){leaveZen();globalThis.scrapsTitle?.show('solo');return;}navigate(replay?'replays':'play');};$('#game-settings').onclick=showSettings;if($('#duel-view'))$('#duel-view').onchange=e=>{prefs.duelView=e.target.checked;save('preferences',prefs);$('.boards').classList.toggle('single',!prefs.duelView);};if($('#edit-board'))$('#edit-board').onclick=()=>{save('freebuild-board',encodeBoard(match.players[0].board));storeReplay(false);stop();showView('freebuild');};if(replay){$('#replay-speed').value=String(replaySpeed);$('#replay-speed').onchange=e=>replaySpeed=Number(e.target.value);$('#replay-restart').onclick=()=>playReplay(replay);}
