// Play vs AI and practice: boards as tall as the window allows, next to the two side panels
function fitLocal(){const g=app.querySelector('.match-grid');if(!g)return;const side=g.querySelector('.match-loadout')?.offsetWidth||230;fitBoards(g,{board:'#wrap-0',room:()=>(innerWidth-2*side-2*58-260)/(g.querySelector('#wrap-1')&&getComputedStyle(g.querySelector('#wrap-1')).display!=='none'?2:1)});}
