// a match's events: sounds, the combo log, combo banners and impacts (also run while a finished match plays out)
function matchEvents(m){for(const s of [0,1])if(!(m.players[s].chain|0))log.close(s);for(const e of m.events){if(zenMode&&!replay&&m===match&&e.side===0&&e.type==='breaking')globalThis.scrapsZen?.combo(e.chain);if(!replay&&e.side===0&&m===match){const k={breaking:'clear',hit:'hit',lock:'lock'}[e.type];if(k)globalThis.scrapsTally?.(k,e.chain);}if(e.type==='breaking'||(match.version===1&&e.type==='clear')){if(e.side===0)sound('clear',e.chain);const desc=e.chain>1?['','','Double','Triple','Bingo','Donkey','Vegas'][Math.min(6,e.chain)]:'Break';log.step(e.side,stepOf(e));if(e.chain>1){const b=$('#banner-'+e.side);b.textContent=`${desc} \u00d7${e.chain}`;b.classList.add('active');setTimeout(()=>b?.classList.remove('active'),950);}if(!prefs.reduced&&match.version===1)for(const c of e.cleared)for(let n=0;n<4;n++)particles[e.side].push({x:c.x,y:c.y,color:c.cell.color,time:performance.now(),vx:(Math.random()-.5)*80,vy:-20-Math.random()*70});}if(e.type==='hit'){strikeTimes[e.side][e.id]=performance.now();if(e.side===0)sound('hit');if(!prefs.reduced){const wrap=$('#wrap-'+e.side);wrap?.classList.add('impact');setTimeout(()=>wrap?.classList.remove('impact'),260);}}if(e.type==='lock'&&e.side===0)sound('lock');}
}
// the match is decided: the last combo and attacks finish on screen, then a finisher if it earned one, then the result
function playoutTick(){const po=ending.po;if(!po.done){po.step(DT);matchEvents(po.state);return;}if(ending.shown)return;ending.shown=true;const w=match.winner;const f=w===0||w===1?finisherOf(log.entries.find(c=>c.who===w)):null;showFinisher(f,{who:w===0?'You':(replay?.opponent??opponent().name),reduced:prefs.reduced,prefs}).then(()=>{if(ending&&ending.po===po)finishGame();});}

function chainHTML(e,who){const n=Math.max(1,e.chain||1),tier=Math.min(6,n),sent=[...(e.swords??[]).map(([w,l])=>`<span class="sent-sword" style="--w:${w};--l:${l}">${w}\u00d7${l}</span>`),e.sprinkles?`<span class="sent-sprinkle">${e.sprinkles}</span>`:''].join('');return `<div class="chain-entry tier-${tier} ${e.side===0?'mine':'theirs'}"><b class="chain-n">${n>1?'\u00d7'+n:'\u2022'}</b><div><strong>${esc(e.desc??'Break')}</strong><small>${esc(who)}${sent?' sent':''}</small><div class="chain-sent">${sent||'<span class="sent-none">nothing sent</span>'}</div></div></div>`;}
function setText(node,value){if(!node)return;const text=String(value);if(node.textContent!==text)node.textContent=text;}
function updateGame(time){if(!running||!match)return;const shown=ending?.po.state??match;for(let i=0;i<2;i++){particles[i]=particles[i].filter(p=>time-p.time<600);drawBoard($('#board-'+i),shown.players[i],{time,gravityMs:match.rules.gravityMs,fastFallMs:match.rules.fastFallMs,ghost:prefs.ghost,particles:particles[i],strikeTimes:strikeTimes[i],reduced:prefs.reduced,renderAheadMs:!paused&&!finished&&!ending&&countdown<=0?acc:0});drawNext($('#next-'+i),pairAt(match.seed,previewIndex(shown.players[i]),match.rules.breakerRate));setText($('#combo-'+i),match.players[i].stats.bestChain?'Best combo: ×'+match.players[i].stats.bestChain:'Best combo: —');const incoming=[...match.players[i].incoming.flatMap(a=>a.attacks??[a]),...(match.players[i].readyAttacks??[]).flatMap(a=>a.attacks??[a]),...(match.players[i].attackVisual?.hits??(match.players[i].attackVisual?[match.players[i].attackVisual.hit]:[]))];setText($('#incoming-'+i),incoming.length?incoming.reduce((n,a)=>n+(a.kind==='sprinkle'?a.count:a.width*a.length),0)+' incoming':'No incoming');$('#incoming-'+i).classList.toggle('hot',!!incoming.length);}
 const p=match.players[0],sec=Math.floor(match.elapsed/1000);if(zenMode)globalThis.scrapsZen?.update(p.stats,match.elapsed,session);setText($('#match-clock'),`${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`);setText($('#duel-clock'),`${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`);setText($('#ppm'),match.elapsed>0?Math.round(p.stats.pieces*60000/match.elapsed):0);setText($('#swords'),p.stats.swords);setText($('#sprinkles'),p.stats.sprinkles);setText($('#best-chain'),p.stats.bestChain?'\u00d7'+p.stats.bestChain:'-');if(log.entries.length&&(updateGame.logRef!==log||updateGame.logVersion!==log.version)){updateGame.logRef=log;updateGame.logVersion=log.version;$('#exchange-log').innerHTML=log.entries.map(c=>comboHTML(c,{who:c.who===0?'You':(replay?.opponent??opponent().name),mine:c.who===0})).join('');}}
function frame(time){const elapsed=Math.min(100,time-(last||time));last=time;if(running&&!paused&&!finished){acc+=elapsed*(replay?replaySpeed:1);let budget=0;while(acc>=DT&&budget++<24){tick();acc-=DT;}}else acc=0;if(running)updateGame(time);requestAnimationFrame(frame);}requestAnimationFrame(frame);
